List Runs For Project.code:
// List runs for a project. Paths are relative to /api/ on your OpenFn host.
get('runs', {
  query: { project_id: $.configuration.projectId },
});

// Keep only failed or crashed runs for alerting.
fn(state => {
  const runs = state.data.runs ?? state.data.data ?? state.data;
  state.failedRuns = runs.filter(r => ['failed', 'crashed'].includes(r.state));
  return state;
});

List Jobs.code:
// List jobs in a project.
get('jobs', {
  query: {
    project_id: $.configuration.projectId,
    limit: 50,
    offset: 0,
  },
});

List Credentials.code:
// List credentials (metadata) for an access audit.
request('GET', 'credentials', {
  errors: { 403: 'This token cannot list credentials' },
});
